import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
	    Scanner sc=new Scanner(System.in);
	    int t=sc.nextInt();
	    while(t-->0){
	        int n=sc.nextInt();
	        long a[]=new long[3*n];
	        for(int i=0;i<3*n;i++){
	            a[i]=sc.nextLong();
	        }
	        Arrays.sort(a);
	        
	        for(int i=0;i<3*n/2;i++){
	            long temp=a[i];
	            a[i]=a[3*n-1-i];
	            a[3*n-1-i]=temp;
	        }
	        long pre[]=new long[3*n+1];
	        for(int i=0;i<3*n;i++){
	            pre[i+1]=pre[i]+a[i];
	        }
	        long res=0;
	        for(int x=0;x<=n;x++){
	            int rem=n-x;
	            int y;
	            if(rem==0){
	                y=0;
	                
	            }else{
    	            int low=0;
    	            int high=rem-1;
    	            while(low<=high){
    	                int mid=low+(high-low)/2;
    	                int p1=x+2*mid;
    	                int p2=3*n-2*x-mid;
    	                long d=a[p1]+a[p1+1]-3*a[p2-1];
    	                if(d>=0){
    	                    low=mid+1;
    	                    
    	                }else{
    	                    high=mid-1;
    	                }
    	            }
    	            y=low;
	            }
	            int p2=3*n-2*x-y;
	            
	            long cur=6*pre[x]+4*(pre[x+2*y]-pre[x])+3*(pre[p2]-pre[x+2*y]);
	            res=Math.max(res,cur);
	        }
	        System.out.println(res);
	    }
		// your code goes here

	}
}
